require_once __DIR__ . '/inc/mother_session.php';
$page_title=$t('M-CARE guidance helper');include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<section class="panel"><header class="panel-heading"><h2 class="panel-title"><?=$t('M-CARE guidance helper')?></h2></header><div class="panel-body">
<p><?=$t('Ask a question. Replies use published guidance in your selected language and pregnancy/postpartum stage. This helper is not a clinician and does not diagnose.')?></p>
<div class="alert alert-warning"><?=$t('For symptoms, use the report form or contact your care team. For urgent warning signs, seek care now.')?></div>
<form id="mcare-guidance-form"><div class="form-group"><label for="mcare-guidance-topic"><?=$t('Choose a topic')?></label><select id="mcare-guidance-topic" class="form-control"><option value="education"><?=$t('General education')?></option><option value="anc"><?=$t('Pregnancy and ANC')?></option><option value="nutrition"><?=$t('Nutrition')?></option><option value="postpartum"><?=$t('After-birth or postpartum care')?></option><option value="appointments"><?=$t('Appointment or referral')?></option><option value="symptoms"><?=$t('Symptoms or urgent concern')?></option></select></div>
<div class="form-group"><label for="mcare-guidance-question"><?=$t('Your question')?></label><textarea id="mcare-guidance-question" class="form-control" rows="4" maxlength="2000" required></textarea></div><button id="mcare-guidance-submit" class="btn btn-primary" type="submit"><?=$t('Get guidance')?></button></form>
<div id="mcare-guidance-status" class="text-muted" role="status" aria-live="polite" style="margin-top:14px"></div><article id="mcare-guidance-answer" class="well" style="display:none;white-space:pre-wrap;margin-top:12px"></article><p class="text-muted"><?=$t('The helper does not store your question or learn from private chats.')?></p>
</div></section></section></div><?php include 'inc/footer.php';include 'inc/scripts.php'; ?>
<script>
(function(){const form=document.getElementById('mcare-guidance-form'),question=document.getElementById('mcare-guidance-question'),button=document.getElementById('mcare-guidance-submit'),status=document.getElementById('mcare-guidance-status'),answer=document.getElementById('mcare-guidance-answer'),csrf=<?=json_encode($_SESSION['csrf_token'])?>;form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;answer.style.display='none';status.textContent=<?=json_encode($t('Finding published guidance…'))?>;try{const p=new URLSearchParams();p.set('_csrf',csrf);p.set('question',question.value.trim());p.set('topic',document.getElementById('mcare-guidance-topic').value);const r=await fetch('mother_assistant',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:p.toString()});const d=await r.json();if(!r.ok)throw new Error(d.error||<?=json_encode($t('The helper is unavailable. Please use live chat.'))?>);answer.textContent=d.reply+(d.sources&&d.sources.length?'\n\n'+<?=json_encode($t('Published guidance:'))?>+' '+d.sources.join(', '):'');answer.style.display='block';status.textContent=<?=json_encode($t('Answer based on published guidance.'))?>;}catch(err){status.textContent=err.message;}finally{button.disabled=false;}});})();
</script>
